widget.prelude:
import copy
import random


def stress(fast, brute, gen, trials, seed):
    rng = random.Random(seed)
    for _ in range(trials):
        case = gen(rng)
        if fast(copy.deepcopy(case)) != brute(copy.deepcopy(case)):
            return case
    return None


def gen_list(rng, n):
    return [rng.randint(1, 3) for _ in range(n)]


def gen_wide(rng, n):
    return [rng.randint(1, 10**6) for _ in range(n)]


def brute_inv(xs):
    return sum(1 for i in range(len(xs)) for j in range(i + 1, len(xs)) if xs[i] > xs[j])


def fast_ties(xs):
    # counts equal pairs as inversions
    return sum(1 for i in range(len(xs)) for j in range(i + 1, len(xs)) if xs[i] >= xs[j])


def fast_no_last(xs):
    # never looks at the last element
    ys = xs[:-1]
    return sum(1 for i in range(len(ys)) for j in range(i + 1, len(ys)) if ys[i] > ys[j])


def fast_adjacent(xs):
    # counts only neighbouring pairs
    return sum(1 for i in range(len(xs) - 1) if xs[i] > xs[i + 1])


def fast_merge(xs):
    # a correct merge-sort count
    def go(a):
        if len(a) <= 1:
            return a, 0
        m = len(a) // 2
        left, x = go(a[:m])
        right, y = go(a[m:])
        out, i, j, c = [], 0, 0, x + y
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                out.append(left[i]); i += 1
            else:
                out.append(right[j]); j += 1; c += len(left) - i
        out += left[i:] + right[j:]
        return out, c
    return go(list(xs))[1]

widget.solution:
def smallest_failing(fast, brute, gen, seed):
    for n in range(1, 9):
        case = stress(fast, brute, lambda rng: gen(rng, n), 200, seed)
        if case is not None:
            return case
    return None
